<script>document.addEventListener('DOMContentLoaded',()=>{const c=document.getElementById('signature-pad'),x=c.getContext('2d');let p=false;const pos=e=>{const r=c.getBoundingClientRect(),t=e.touches?e.touches[0]:e;return [(t.clientX-r.left)*c.width/r.width,(t.clientY-r.top)*c.height/r.height]};const start=e=>{p=true;x.beginPath();x.moveTo(...pos(e));e.preventDefault()};const move=e=>{if(!p)return;x.lineWidth=2;x.lineCap='round';x.lineTo(...pos(e));x.stroke();e.preventDefault()};['mousedown','touchstart'].forEach(n=>c.addEventListener(n,start,{passive:false}));['mousemove','touchmove'].forEach(n=>c.addEventListener(n,move,{passive:false}));['mouseup','mouseleave','touchend'].forEach(n=>c.addEventListener(n,()=>p=false));document.getElementById('clear-signature').onclick=()=>x.clearRect(0,0,c.width,c.height);document.getElementById('signature-form').onsubmit=()=>document.getElementById('signature').value=c.toDataURL('image/png')})</script>
